mapper.select:
SELECT
    tp.participant_code,
    /* 1. 사용자 정보 테이블(tui)에 이름이 있으면 그것을 쓰고, 없으면 tp.user_info_seq에 담긴 문자열을 이름으로 간주 */
    COALESCE(tui.user_name_ko, tp.user_info_seq) AS user_name_ko,
    tp.user_info_seq
FROM utb_participant tp
         /* 2. INNER JOIN에서 LEFT JOIN으로 변경 (사용자 정보가 없어도 관계자 행이 조회되도록 함) */
         LEFT JOIN utb_user_info tui ON tp.user_info_seq = tui.user_info_seq
WHERE tp.tbl_seq = #{tblSeq}
  AND tp.office_seq = #{officeSeq}
  AND tp.main_yn = 'Y'
  AND tp.del_yn = 'N'

mapper.update:
UPDATE utb_participant
SET del_yn = 'N',
    update_at = CURRENT_TIMESTAMP
WHERE tbl_seq = #{tblSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'Y'    /* 활성 상태인 건만 비활성화 */

mapper.select:
SELECT DISTINCT p.tbl_seq
FROM utb_participant p
INNER JOIN utb_user_info u ON p.user_info_seq = u.user_info_seq
WHERE p.office_seq = #{officeSeq}
AND p.del_yn = 'N'
AND (

    (
    p.${item.codeCol} = #{item.codeVal}


            AND u.user_name_ko LIKE CONCAT('%', #{item.value}, '%')


            AND p.user_info_seq = #{item.value}


    )

)
